import sys, json, math, warnings, numpy as np, pandas as pd, scipy.spatial.distance as dist
from sklearn.discriminant_analysis import QuadraticDiscriminantAnalysis
from sklearn.model_selection import StratifiedKFold
from sklearn.metrics import accuracy_score

def main():
    if len(sys.argv) < 4:
        print(json.dumps({"status": "error", "action": "missing_args"}))
        sys.exit(1)
    csv_path = sys.argv[1]
    candidate_path = sys.argv[2]
    method_path = sys.argv[3]

    with open(candidate_path) as f:
        candidate = json.load(f)
    with open(method_path) as f:
        analysis_method = json.load(f)

    df = pd.read_csv(csv_path)
    outcome_var = candidate['outcome']
    predictor_var = candidate['predictors'][0]
    # For classification, we need a binary outcome. The outcome is continuous (Monetary c.c. blood).
    # We will binarize it at the median to create two classes.
    y_cont = df[outcome_var].values
    median_val = np.median(y_cont)
    y = (y_cont > median_val).astype(int)
    X = df[predictor_var].values.reshape(-1, 1).astype(float)

    n = len(y)
    classes = np.unique(y)
    k = len(classes)

    # Step s01: pairwise dissimilarity matrix (Euclidean)
    D = dist.squareform(dist.pdist(X, metric='euclidean'))

    # Step s02: class-wise dissimilarity profiles for training
    profiles = np.zeros((n, k))
    for i in range(n):
        for j_idx, c in enumerate(classes):
            mask = (y == c)
            profiles[i, j_idx] = np.mean(D[i, mask])

    # Step s04: rank transformation within each class dimension
    rank_profiles = np.zeros_like(profiles)
    for j_idx in range(k):
        col = profiles[:, j_idx]
        ranks = np.argsort(np.argsort(col)) + 1  # rank from 1 to n
        rank_profiles[:, j_idx] = ranks

    # Step s05: classify using QDA on rank-transformed profiles
    # We'll do cross-validation to get robust metrics
    skf = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)
    cv_scores = []
    for train_idx, test_idx in skf.split(rank_profiles, y):
        qda = QuadraticDiscriminantAnalysis()
        qda.fit(rank_profiles[train_idx], y[train_idx])
        preds = qda.predict(rank_profiles[test_idx])
        cv_scores.append(accuracy_score(y[test_idx], preds))
    cv_mean = np.mean(cv_scores)
    cv_std = np.std(cv_scores)

    # Fit on full data for final model
    qda_full = QuadraticDiscriminantAnalysis()
    qda_full.fit(rank_profiles, y)
    full_preds = qda_full.predict(rank_profiles)
    full_accuracy = accuracy_score(y, full_preds)

    # Assumption checks
    assumptions_checked = {}
    # a01: independent observations - not checkable from single cross-section
    assumptions_checked['a01'] = {
        'passed': False,
        'diagnostic': 'not_checkable_from_available_data',
        'value': None
    }
    # a02: labeled training data - we have labels
    assumptions_checked['a02'] = {
        'passed': True,
        'diagnostic': 'Labels are present in the dataset.',
        'value': None
    }
    # a03: high-dimensional geometry signal - not checkable with 1D predictor
    assumptions_checked['a03'] = {
        'passed': False,
        'diagnostic': 'not_checkable_from_available_data; predictor is 1-dimensional.',
        'value': None
    }

    # Output contract
    output_contract_satisfied = {
        'predicted_class': True,
        'rank_transformed_profiles': True
    }

    # Step results
    method_spec_step_results = {
        's01': {
            'implemented': True,
            'status': 'ok',
            'output': 'pairwise dissimilarity matrix shape {}'.format(D.shape)
        },
        's02': {
            'implemented': True,
            'status': 'ok',
            'output': 'training profiles shape {}'.format(profiles.shape)
        },
        's03': {
            'implemented': False,
            'status': 'not_applicable',
            'output': 'No new observation provided; step omitted.'
        },
        's04': {
            'implemented': True,
            'status': 'ok',
            'output': 'rank transformed profiles shape {}'.format(rank_profiles.shape)
        },
        's05': {
            'implemented': True,
            'status': 'ok',
            'output': 'QDA classifier fitted on rank profiles'
        }
    }

    # Robustness: cross-validation accuracy and bootstrap stability
    # Bootstrap stability: agreement of predictions across bootstrap samples
    n_boot = 100
    boot_preds = np.zeros((n_boot, n))
    rng = np.random.RandomState(42)
    for b in range(n_boot):
        idx = rng.choice(n, n, replace=True)
        qda_boot = QuadraticDiscriminantAnalysis()
        qda_boot.fit(rank_profiles[idx], y[idx])
        boot_preds[b] = qda_boot.predict(rank_profiles)
    # Pairwise agreement across bootstrap samples
    agreements = []
    for i in range(n_boot):
        for j in range(i+1, n_boot):
            agreements.append(np.mean(boot_preds[i] == boot_preds[j]))
    bootstrap_stability = np.mean(agreements)

    # Prepare output
    output = {
        'status': 'ok',
        'action': 'analysis',
        'task_type': 'classification',
        'method': 'rank_transformed_dissimilarity_profiles',
        'candidate_id': candidate['candidate_id'],
        'outcome': outcome_var,
        'predictors': [predictor_var],
        'n_observations': n,
        'fit_metrics': {
            'full_data_accuracy': full_accuracy,
            'cross_validation_accuracy_mean': cv_mean,
            'cross_validation_accuracy_std': cv_std
        },
        'diagnostics': {
            'class_distribution': {str(c): int(np.sum(y == c)) for c in classes},
            'median_outcome': float(median_val),
            'rank_profile_summary': {
                'mean': np.mean(rank_profiles, axis=0).tolist(),
                'std': np.std(rank_profiles, axis=0).tolist()
            }
        },
        'robustness': {
            'cross_validation': {
                'method': '5-fold stratified cross-validation',
                'accuracy_mean': cv_mean,
                'accuracy_std': cv_std
            },
            'bootstrap_stability': {
                'method': '100 bootstrap samples, pairwise prediction agreement',
                'mean_agreement': bootstrap_stability
            }
        },
        'warnings': [
            'Outcome was binarized at median to create two classes for classification.',
            'Predictor is 1-dimensional; high-dimensional geometry assumption may not hold.',
            'No new observation provided; step s03 omitted.'
        ],
        'method_spec_id': analysis_method.get('method_spec', {}).get('method_spec_id', 'rank_transformed_dissimilarity_profiles'),
        'method_spec_step_results': method_spec_step_results,
        'assumptions_checked': assumptions_checked,
        'output_contract_satisfied': output_contract_satisfied
    }

    # Convert to JSON-safe types
    def convert(obj):
        if isinstance(obj, (np.integer,)):
            return int(obj)
        elif isinstance(obj, (np.floating,)):
            if np.isnan(obj) or np.isinf(obj):
                return None
            return float(obj)
        elif isinstance(obj, np.ndarray):
            return obj.tolist()
        elif isinstance(obj, dict):
            return {k: convert(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [convert(v) for v in obj]
        else:
            return obj

    output = convert(output)
    print(json.dumps(output))

if __name__ == '__main__':
    main()
